code.formula:
@Command([EditDocument];"1");

@If (SendTo= ""; @Return(@Do(@Command([EditGotoField];"SendTo") ;@Prompt([Ok];"Missing Value"; "Please select the PIC!")));"");
@If (Desc= ""; @Return(@Do(@Command([EditGotoField];"Desc") ;@Prompt([Ok];"Missing Value"; "Please state the Description!")));"");
@If (position= ""; @Return(@Do(@Command([EditGotoField];"position") ;@Prompt([Ok];"Missing Value"; "Please insert your Position!")));"");

FIELD Notified := @V3UserName;
FIELD reportedDate :=@Today;
FIELD CurrentAction :="Submitted";

@Command([FileSave]);

@MailSend(SendTo;Defcc:cc;NULL;"Night Duty Inspection Form - Sent for REVIEW: "  +  txtINNumberC ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

FIELD SubmittedBy := @V3UserName;
FIELD SubmittedOn :=@Today;
FIELD CurrentAction :="Completed";

@Command([FileSave]);

@MailSend(SendTo;Defcc:cc;NULL;"Night Duty Inspection Form - Completed : "  +  txtINNumberC ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

par.button:
ludb :="PHBSVR/PHB": "Current/NightDuty.nsf";
luview := "Dept_PIC";
Title:="Department - PIC";
Prompt:="Select a record";
lucol:=3;

AllData:=@PickList([Custom];ludb;luview;title;prompt;lucol);

SelDept := @Word(AllData;"~";1);
SelPIC 	  := @Word(AllData;"~";2);

FIELD Dept := @Trim(SelDept);
FIELD PIC	  := @Trim(SelPIC);

